  },
  "required": [
    "report"
  ]
}

{
  "type": "object",
  "properties": {
    "target": {
      "type": "string",
      "description": "Numeric id or range from a context marker, e.g. \"5\" or \"2-6\". Omit to list the hidden-segment index."
    },
    "action": {
      "type": "string",
      "description": "Tier 2 segment management (issue #1379). With a target: \"hide\" folds a dead-weight segment into its expandable marker right now, without waiting for pressure; \"pin\" shields a segment from every hide/compact path; \"unpin\" releases it. Omit to expand the target."
    },
    "query": {
      "type": "string",
      "description": "Search the hidden segments (preview and full content) when you know WHAT you need but not the id. Free — no budget."
    },
    "page": {
      "type": "integer",
      "description": "1-based page for giant segments (default 1)",
      "minimum": 1
    }
  },
  "required": []
}

{
  "type": "object",
  "properties": {
    "query": {
      "type": "string",
      "description": "The phrase to search for (keyword, or a regular expression with regex: true). Required in search mode."
    },
    "scope": {
      "type": "string",
      "enum": [
        "branch",
        "tree"
      ],
      "description": "branch (default) searches the active branch only; tree spans forks and abandoned branches too."
    },
    "mode": {
      "type": "string",
      "enum": [
        "search",
        "map"
      ],
      "description": "search (default) finds records; map reports the archive structure (counts, hidden totals, checkpoint tree)."
    },
    "kinds": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Only these record types (message, compaction, compact_checkpoint, custom, …). Empty keeps every kind."
    },
    "before": {
      "type": "string",
      "description": "Only records older than this ISO-8601 instant."
    },
    "after": {
      "type": "string",
      "description": "Only records newer than this ISO-8601 instant."
    },
    "regex": {
      "type": "boolean",
      "description": "Match query as a case-insensitive regular expression (default: literal keyword)."
    },
    "maxHits": {
      "type": "integer",
      "description": "Cap on returned pointers (default 40, max 200). A capped scan returns a continuation token."
    },
    "continuation": {
      "type": "integer",
      "description": "The token a previous capped call returned — resumes the scan after the records already examined."
    }
  }
}

content.text:
/// The compact tool-row grammar (issue #366): every builtin tool renders as
/// `<glyph> <label> · <detail> <elapsed>` — oh-my-pi-style, brand-colored,
/// budget-aware.
///
/// Pure layout + human-detail extraction; palette escapes are NEVER baked
/// here. Width math runs on RAW text (the #279 E1 rule): the caller styles
/// the laid-out segments at emit time via [LaidOutToolRow.style], so a
/// mid-session `/theme` switch is honored by the next row and the `…` the
/// fitter appended is painted with its segment, not pre-colored.
///
/// The visible row never carries the raw tool-argument JSON envelope: the
/// detail is the question text, the command, or the path — see
/// [toolRowDetail].
library;

import 'tui_text_width.dart';

/// A tool row's lifecycle state (issue #444): the row's border role is
/// picked by state, never hardcoded — running rows carry the accent
/// border, settled rows the quiet muted border, done/failed rows the
/// success/error tints.
enum ToolRowState { running, settled, done, failed }

/// One tool row's content, ready for layout.
final class ToolRowSegments {
  const ToolRowSegments({
    required this.glyph,
    required this.label,
    this.detail = '',
    this.elapsed = '',
  });

  /// The state marker (`•` running, `✓` done, `✗` error).
  final String glyph;

  /// The short tool name (`ask`, `bash`, `read`, …).
  final String label;

  /// The human detail (question text, command, path). Empty = the grammar
  /// degrades to glyph+label with no dangling `·` (issue #366 E2).
  final String detail;

  /// The dim trailing zone: `Ns` elapsed on end rows, or the `/tasks` job
  /// suffix (id + relativized log path).
  final String elapsed;
}

/// A row laid out within the width budget: every segment already fitted,
/// the `·` separator present only when a detail survived (E2).
final class LaidOutToolRow {
  const LaidOutToolRow(this.parts);

  /// Raw segments in print order (`glyph`, `label`, `·`, detail, elapsed);
  /// empty segments and the separator-when-no-detail are already dropped.
  final List<String> parts;

  /// The plain (unstyled) row.
  String join() => parts.join(' ');

  /// Paints the row at emit time: the glyph carries the state color, the
  /// label the bold tool-title accent, detail/separator/elapsed the muted
  /// role. Painters receive RAW text and return SGR-wrapped text.
  String style({
    required String Function(String) glyph,
    required String Function(String) label,
    required String Function(String) dim,
  }) {
    final painted = <String>[
      for (final (i, part) in parts.indexed)
        switch (i) {
          0 => glyph(part),
          1 => label(part),
          _ => dim(part),
        },
    ];
    return painted.join(' ');
  }
}

/// Lays one row out on [width] terminal cells (grapheme-safe): the label
/// and the trailing zone always fit in full (issue #366 AC2) — only the
/// detail absorbs a narrow terminal, ellipsized via [tuiFitWidth] and only
/// when the budget is genuinely exceeded.
LaidOutToolRow layoutToolRow(ToolRowSegments s, int width) {
  // Unbounded budget (width <= 0): the headless/line-mode log keeps the
  // FULL command (issue #638 AC3) — only a real viewport clips. Still one
  // physical line (issue #599).
  if (width <= 0) {
    return LaidOutToolRow([
      if (s.glyph.isNotEmpty) s.glyph,
      if (s.label.isNotEmpty) s.label,
      if (s.detail.isNotEmpty) ...['·', _flatten(s.detail)],
      if (s.elapsed.isNotEmpty) s.elapsed,
    ]);
  }
  final w = width;
  final glyphW = s.glyph.isEmpty ? 0 : tuiTextWidth('${s.glyph} ');
  final elapsedW = s.elapsed.isEmpty ? 0 : tuiTextWidth(' ${s.elapsed}');
  // Degenerate guard: even a label wider than the row stays on one line
  // (capped), because a soft-wrapped chrome row desyncs the renderer.
  final label = tuiFitWidth(s.label, (w - glyphW - elapsedW).clamp(1, w));
  final used = glyphW + tuiTextWidth(label) + elapsedW;
  final detailBudget = w - used - tuiTextWidth(' · ');
  final detail = s.detail.isEmpty || detailBudget < 1
      ? ''
      : tuiFitWidth(_flatten(s.detail), detailBudget);
  return LaidOutToolRow([
    if (s.glyph.isNotEmpty) s.glyph,
    label,
    if (detail.isNotEmpty) ...['·', detail],
    if (s.elapsed.isNotEmpty) s.elapsed,
  ]);
}

/// The human detail for a tool call (issue #366): the `ask` question text,
/// the `bash` command (`cd …/ && …` collapsed to the meaningful tail),
/// `read` → `path:lines`, `write`/`edit` → the path — never the JSON
/// envelope. Unknown tools degrade to their first string argument; no
/// string argument means an empty detail (E2).
String toolRowDetail(
  String toolName,
  Map<String, dynamic> args, {
  String? cwd,
  String? home,
}) {
  switch (toolName) {
    case 'ask':
      return _askDetail(args);
    case 'bash':
      // Heredoc-aware (issue #599): first line + `…`, taken BEFORE the
      // flatten — flattened, the heredoc body would leak into the row as
      // words. A single-line command passes through untouched (E2).
      return shellJobCommandPreview(collapseCd(_rawFirstString(args)));
    case 'read':
      return _readDetail(args, cwd: cwd, home: home);
    case 'write':
    case 'edit':
    case 'ls':
    case 'bash_job':
      return _actionDetail(args);
    default:
      return _firstString(args);
  }
}

String _askDetail(Map<String, dynamic> args) {
  final questions = args['questions'];
  if (questions is List && questions.isNotEmpty) {
    final first = questions.first;
    if (first is Map && first['question'] is String) {
      return (first['question'] as String).trim();
    }
  }
  return _firstString(args);
}

String _readDetail(Map<String, dynamic> args, {String? cwd, String? home}) {
  final path = _firstString(args);
  if (path.isEmpty) return '';
  final offset = args['offset'];
  final limit = args['limit'];
  final lines = offset is num
      ? (limit is num
            ? ':${offset.toInt()}-${limit.toInt()}'
            : ':${offset.toInt()}')
      : '';
  return '${_briefPath(path, cwd: cwd, home: home)}$lines';
}

String _actionDetail(Map<String, dynamic> args) {
  final action = _firstString(args);
  final id = args['id'];
  return id is String && id.isNotEmpty ? '$action $id' : action;
}

/// Collapses a leading `cd <dir> && …` compound to the meaningful tail
/// (issue #366): the directory is job-site plumbing, the tail is the news.
String collapseCd(String command) {
  final match = RegExp(r'^cd\s+.+?\s*&&\s*(\S.*)$').firstMatch(command);
  return match == null ? command : match.group(1)!;
}

/// Heredoc-aware command preview (issue #599): the first line, plus `…`
/// when the command has more lines. The heredoc body is never a
/// transcript row source, and a missing `EOF` terminator changes nothing
/// — there is no body parsing (E1).
String shellJobCommandPreview(String command) {
  final nl = command.indexOf('\n');
  if (nl < 0) return command;
  return '${command.substring(0, nl)}…';
}

/// Project-relative when under [cwd], `~`-collapsed when under [home],
/// otherwise untouched (issue #366 point 4).
String briefPath(String path, {String? cwd, String? home}) =>
    _briefPath(path, cwd: cwd, home: home);

String _briefPath(String path, {String? cwd, String? home}) {
  var p = path;
  final c = cwd ?? '';
  if (c.isNotEmpty && (p == c || p.startsWith('$c/'))) {
    p = p == c ? '.' : p.substring(c.length + 1);
  }
  final h = home ?? '';
  if (h.isNotEmpty && (p == h || p.startsWith('$h/'))) {
    p = '~${p.substring(h.length)}';
  }
  return p;
}

/// The first String value in insertion order, whitespace-flattened — the
/// generic fallback that keeps unknown/MCP tools inside the grammar without
/// ever JSON-encoding an envelope.
String _firstString(Map<String, dynamic> args) =>
    _flatten(_rawFirstString(args));

/// The first String value in insertion order, newlines intact — callers
/// that must see the original line structure (the issue #599 bash
/// preview) use this; [_firstString] stays the flattened default.
String _rawFirstString(Map<String, dynamic> args) {
  for (final value in args.values) {
    if (value is String && value.trim().isNotEmpty) return value.trim();
  }
  return '';
}
/// One display row, one line: newlines flatten to spaces, whitespace runs
/// collapse (a two-line compound command stays a single row).
String _flatten(String text) => text.replaceAll(RegExp(r'\s+'), ' ').trim();

/// Duration and token formatting shared by trajectory consumers.
///
/// Ported from deepseek-harness `packages/client/ui-trajectory/src/client/
/// trajectory-record.ts` (`formatDurationMillis`, `formatElapsedSeconds`).
/// Locale-free: labels are fixed strings, thousands are comma-separated.
library;

/// The label used when a value is absent or not finite.
const _unknownLabel = '—';

/// Formats a duration in milliseconds with thousands separators.
///
/// Returns [_unknownLabel] for null, and clamps negative values to zero.
String formatDurationMillis(int? milliseconds) {
  if (milliseconds == null) return _unknownLabel;
  final integer = (milliseconds < 0 ? 0 : milliseconds).toString();
  return integer.replaceAllMapped(_thousands, (match) => ',');
}

/// Formats an elapsed duration given in seconds as a millisecond label.
///
/// Returns [_unknownLabel] for null or non-finite input; negative values
/// clamp to zero.
String formatElapsedSeconds(double? seconds) {
  if (seconds == null || seconds.isNaN || seconds.isInfinite) {
    return _unknownLabel;
  }
  return formatDurationMillis((seconds * 1000).round());
}

/// Formats a token count compactly (`999`, `12.3k`, `1.2M`).
///
/// Returns [_unknownLabel] for null.
String formatTokens(int? tokens) {
  if (tokens == null) return _unknownLabel;
  if (tokens < 1000) return '$tokens';
  if (tokens < 1000000) return '${_trim(_scale(tokens, 1000))}k';
  return '${_trim(_scale(tokens, 1000000))}M';
}

final RegExp _thousands = RegExp(r'\B(?=(\d{3})+(?!\d))');

double _scale(int value, int unit) => value / unit;

/// Drops a trailing `.0` from a one-decimal compact value.
String _trim(double value) {
  final fixed = value.toStringAsFixed(1);
  return fixed.endsWith('.0') ? fixed.substring(0, fixed.length - 2) : fixed;
}

import '../context.dart';
import '../session/session_tree.dart'
    show branchSummaryPrefix, compactionSummaryPrefix;
import '../types.dart';
import 'system_notice_render.dart';
import 'tool_rows.dart';
import 'tui_chrome.dart';
import 'tui_theme.dart';

/// The restored-transcript renderer (issue #446): ONE pipeline for live and
/// replayed history. Every row type the live TUI draws is drawn here by the
/// SAME builder — tool rows through the live end-row grammar ([tuiToolCard]
/// band chrome since #807, [layoutToolRow] under the chrome kill switch,
/// [toolRowDetail] for the detail), system notices through
/// [renderSystemNoticeLines], assistant text as raw markdown the view
/// styles at render time — so a reopened session looks exactly like the
/// moment the terminal was closed (issue #916: the replay rides the same
/// chrome migration as the live edge by default — the `tuiChromeEnabled`
/// kill switch and line mode intentionally keep the legacy row,
/// byte-pinned).
///
/// The only permitted live/replay difference is honest lossy bits: replayed
/// tool rows carry no live durations (the `—` elapsed meta where a live
/// card shows `3s`) and spinners never render from replay.

/// A code-fence opener/closer line (```). Tracked by the replay so a
/// truncated message never leaves a dangling fence: the view formats the
/// whole history as ONE markdown stream, and an unclosed fence would render
/// everything after it as verbatim code (raw `**`, tables, links).
final _fenceLineRe = RegExp(r'^\s*```');

/// The streamed-assistant prefix (`>_Fa `), byte-identical live and
/// replayed: bold first-accent `>_` plus bold `Fa`. The live stream emits it
/// once per assistant message before the first text delta; the replay puts
/// it on the replayed message's first text row.
String assistantStreamPrefix() =>
    '\x1b[1m${tuiAccentSoft('>_')}\x1b[0m\x1b[1mFa\x1b[0m ';

/// Appends a synthetic closing fence when [rows] (a truncated assistant
/// message) ends inside a fenced code block.
void _closeDanglingFence(List<String> rows) {
  final open = rows.fold<bool>(
    false,
    (open, row) => open != _fenceLineRe.hasMatch(row),
  );
  if (open) rows.add('```');
}

/// The tool row a persisted [ToolCall] replays as — the live end-row
/// grammar fed from the record itself: the settled band card through the
/// SHARED builder the live `_onToolExecutionEnd` paints
/// ([settledToolCardRows], issue #916) in chrome mode, the legacy painted
/// row under the [tuiChromeEnabled] kill switch, the plain unpainted row in
/// line mode. Name + args preview; the attached result's first line on
/// errors. A call whose result never landed (crash mid-turn) renders in
/// its interrupted state from the args — never a bare `[name]` marker. The
/// card's meta zone carries the honest `—` where a live card shows the
/// elapsed cell (issue #446 contract point 2).
String replayToolRow(
  ToolCall call,
  ToolResultMessage? result, {
  required int width,
  String? cwd,
  String? home,
  bool styled = true,
}) {
  final detail = toolRowDetail(call.name, call.arguments, cwd: cwd, home: home);
  // TUI chrome (issue #916): the settled card IS the live end-row grammar
  // since #807 — both edges render through [settledToolCardRows], so the
  // parity cannot drift again. Line mode and the kill switch keep the
  // legacy row.
  if (styled && tuiChromeEnabled) {
    return settledToolCardRows(
      toolName: call.name,
      successDetail: detail,
      isError: result != null && result.isError,
      width: width,
      resultContent: result?.content ?? const <ContentBlock>[],
      // The one permitted live/replay difference: no live duration.
      meta: const ['—'],
      interrupted: result == null,
    ).join('\n');
  }
  final failed = result == null || result.isError;
  final hasError = result != null && result.isError;
  final row = layoutToolRow(
    ToolRowSegments(
      glyph: failed ? '✗' : '✓',
      label: call.name,
      // The failure text is the news: bright first line, like the live row.
      detail: hasError ? failureFirstLine(result.content) : detail,
      elapsed: '—',
    ),
    width,
  );
  return styled
      ? row.style(
          // An interrupted call keeps the soft glyph paint — only a real
          // error result paints the error role.
          glyph: hasError ? tuiError : tuiAccentSoft,
          label: tuiAccent2,
          dim: hasError ? (String s) => s : tuiDim,
        )
      : row.join();
}

/// The TUI-mode projection of a restored user message: the same background
/// echo box the live submit draws; compaction/branch summaries render as
/// one compact chrome row; `<system-notice>` blocks ride the SAME
/// system-row renderer the live output path uses ([renderSystemNoticeLines]
/// — dim `> ⚙` blockquotes, never the raw fallback marker).
List<String> _replayUserTui(
  Object content,
  int width,
  String Function(String) dim,
) {
  final text = _blocksText(content);
  if (text.trim().isEmpty) return const [];
  final summary = _summaryMarker(text);
  if (summary != null) {
    final (label, firstLine) = summary;
    final hint = firstLine.isEmpty ? '' : ' — $firstLine';
    final markerLine = '$label$hint';
    // The divider fits the label to the terminal width itself (cells, not
    // UTF-16 units) — a wrapped chrome row desyncs the renderer.
    // The divider chrome (issue #807): short rule + label, the omp
    // `message-divider.ts` shape (`tuiMessageDividerLayout`), at the
    // session-resume boundary — the production call site. Painted through
    // the host's dim seam ([dim] = tuiDim live, the test fake in UTs),
    // byte-identical to [tuiMessageDividerBlock] in the live host.
    return ['', dim(tuiMessageDividerLayout(markerLine, width)), ''];
  }
  if (needsSystemNoticeRewrite(text)) return renderSystemNoticeLines(text);
  // Chrome mode (issue #807): the SAME builder the live submit echo uses —
  // resume replay produces identical chrome (issue #807 AC4.5). Legacy
  // mode keeps the rule + bare backgrounded rows.
  if (tuiChromeEnabled) return [...tuiUserBubble(text.split('\n')), ''];
  final bg = tuiUserMessageBgSgr();
  const reset = '\x1b[0m';
  return [
    dim('─' * width),
    for (final line in text.split('\n')) '$bg$line$reset',
    '',
  ];
}

/// The text of a message content: the raw string, or its text blocks joined.
String _blocksText(Object content) {
  return content is String
      ? content
      : (content as List<ContentBlock>)
            .whereType<TextContent>()
            .map((b) => b.text)
            .join('\n');
}

/// The one-line chrome marker for a compaction/branch summary, or null.
String? _summaryMarkerLine(String text) {
  final summary = _summaryMarker(text);
  if (summary == null) return null;
  final (label, firstLine) = summary;
  final hint = firstLine.isEmpty ? '' : ' — $firstLine';
  return '$label$hint';
}

(String label, String firstLine)? _summaryMarker(String text) {
  final isCompaction = text.startsWith(compactionSummaryPrefix);
  if (!isCompaction && !text.startsWith(branchSummaryPrefix)) return null;
  final body = text.substring(
    (isCompaction ? compactionSummaryPrefix : branchSummaryPrefix).length,
  );
  var firstLine = '';
  for (final line in body.split('\n')) {
    final trimmed = line.trim();
    if (trimmed.isNotEmpty && !trimmed.startsWith('<')) {
      firstLine = trimmed;
      break;
    }
  }
  return (
    isCompaction
        ? '⋮ context compacted into a summary'
        : '⋮ summary of the detour branch',
    firstLine,
  );
}

/// Whether the text is replay chrome (system notice / compaction or branch
/// summary) the composer's ↑ input history must skip. Rendering goes
/// through the row builders; this is detection only.
bool _isChromeText(String text) =>
    needsSystemNoticeRewrite(text) || _summaryMarker(text) != null;

/// TUI-mode replay entry in the ACTIVE session's format: the user message
/// as the live submit echo box (notices via the system-row renderer), the
/// assistant message as dimmed thinking rows, the `>_Fa `-prefixed raw
/// markdown text the view styles exactly like a live stream, and one
/// settled tool row per persisted call ([replayToolRow]).
List<String> replayLinesTui(
  Message message, {
  required int width,
  required String Function(String) dim,
  Map<String, ToolResultMessage> results = const {},
  String? cwd,
  String? home,
}) {
  switch (message) {
    case UserMessage(:final content):
      return _replayUserTui(content, width, dim);
    case AssistantMessage(:final content):
      final rows = <String>[];
      for (final block in content.whereType<ThinkingContent>()) {
        // Reasoning replays dim like the live stream showed it (TUI only
        // live; the dim rows are the restored transcript's memory of it).
        rows.addAll(
          block.thinking
              .split('\n')
              .map((line) => line.trim().isEmpty ? line : dim(line)),
        );
      }
      final texts = content
          .whereType<TextContent>()
          .map((b) => b.text)
          .join('\n')
          .trim();
      var firstText = true;
      if (texts.isNotEmpty) {
        for (final line in texts.split('\n')) {
          // The live stream prints the `>_Fa ` prefix once per message,
          // before the first text delta — the replay mirrors it.
          rows.add(firstText ? '${assistantStreamPrefix()}$line' : line);
          firstText = false;
        }
      }
      for (final call in content.whereType<ToolCall>()) {
        rows.add(
          replayToolRow(
            call,
            results[call.id],
            width: width,
            cwd: cwd,
            home: home,
          ),
        );
      }
      return rows;
    default:
      return const [];
  }
}

/// One line-mode replay entry: the compact `you: `/`fa:  ` prefixed
/// projection. `maxRows <= 0` (the default through [buildReplayEntries])
/// replays the message IN FULL — the global row budget bounds which
/// messages replay instead. Assistant text renders plain (line mode has no
/// markdown), tool calls as unpainted tool rows — the same
/// [replayToolRow] grammar, never `[name]` markers.
List<String> replayLines(
  Message message, {
  required int maxRows,
  Map<String, ToolResultMessage> results = const {},
  String? cwd,
  String? home,
}) {
  final prelude = _replayUserPrelude(message);
  if (prelude != null) return prelude;
  final (prefix, body) = _replayPrefixAndBody(
    message,
    results: results,
    cwd: cwd,
    home: home,
  );
  if (body.trim().isEmpty) return const [];
  final rows = body.split('\n');
  final head = maxRows > 0 ? rows.take(maxRows).toList() : rows;
  final suffix = maxRows > 0 && rows.length > maxRows ? ' …' : '';
  if (suffix.isNotEmpty) _closeDanglingFence(head);
  return _prefixReplayRows(head, prefix, suffix);
}

/// The user-message fast paths: summary markers and system-notice
/// rewrites render verbatim, bypassing the prefix projection. Null =
/// fall through to the regular prefix/body rendering.
List<String>? _replayUserPrelude(Message message) {
  if (message case UserMessage(:final content)) {
    final text = _blocksText(content);
    final summaryLine = _summaryMarkerLine(text);
    if (summaryLine != null) return [summaryLine];
    if (needsSystemNoticeRewrite(text)) return renderSystemNoticeLines(text);
  }
  return null;
}

/// The `(prefix, body)` pair for one replayed message: `you: ` over user
/// text, `fa:  ` over assistant text + tool rows, and an empty pair for
/// anything else (results never render standalone).
(String, String) _replayPrefixAndBody(
  Message message, {
  required Map<String, ToolResultMessage> results,
  required String? cwd,
  required String? home,
}) => switch (message) {
  UserMessage(:final content) => ('you: ', _blocksText(content)),
  AssistantMessage(:final content) => (
    'fa:  ',
    [
      content.whereType<TextContent>().map((b) => b.text).join('\n').trim(),
      for (final call in content.whereType<ToolCall>())
        replayToolRow(
          call,
          results[call.id],
          width: 80,
          cwd: cwd,
          home: home,
          styled: false,
        ),
    ].where((s) => s.isNotEmpty).join('\n'),
  ),
  _ => ('', ''),
};

/// Hangs [prefix] (first row), the matching indent (the rest), and the
/// [suffix] (last row) over the replay rows.
List<String> _prefixReplayRows(
  List<String> head,
  String prefix,
  String suffix,
) {
  final indent = ' ' * prefix.length;
  return [
    for (var i = 0; i < head.length; i++)
      '${i == 0 ? prefix : indent}${head[i]}${i == head.length - 1 ? suffix : ''}',
  ];
}

/// The TUI composer's submitted-message history for a restored session:
/// the plain user-typed messages, oldest first — the same set live submits
/// record (no slash/bang commands, no system-notice/compaction chrome,
/// consecutive duplicates collapsed, last 100 kept). Restoring it makes ↑
/// recall the previous message right after a resume instead of scrolling
/// the transcript (issue #47).
List<String> restoredInputHistory(List<Message> messages) {
  final history = <String>[];
  for (final message in messages) {
    if (message is! UserMessage) continue;
    final text = _blocksText(message.content);
    if (text.trim().isEmpty ||
        text.startsWith('/') ||
        text.startsWith('!') ||
        _isChromeText(text)) {
      continue;
    }
    if (history.isEmpty || history.last != text) history.add(text);
  }
  return history.length > 100 ? history.sublist(history.length - 100) : history;
}

/// Builds the replay entries for a restored session's transcript: whole
/// per-message entries (user/assistant in FULL — no per-message head caps;
/// [maxRowsPerMessage] <= 0 means unlimited) filling [rowBudget] from the
/// END. A typical session replays verbatim; a marathon one drops OLDER
/// WHOLE messages rather than decapitating the tail's content. Tool results
/// attach to their calls' rows (see [replayToolRow]); they never render
/// standalone.
(List<List<String>> entries, int firstIndex) buildReplayEntries(
  List<Message> messages, {
  required bool tui,
  required int width,
  required String Function(String) dim,
  String? cwd,
  String? home,
  int rowBudget = 1900,
  int maxRowsPerMessage = 0,
}) {
  // Pair persisted results with their calls up front so each replayed call
  // renders its attached result (name + args preview + result), the same
  // material the live end row had.
  final results = {
    for (final message in messages)
      if (message is ToolResultMessage) message.toolCallId: message,
  };
  final entries = <List<String>>[];
  var firstIndex = messages.length;
  var rows = 0;
  for (var i = messages.length - 1; i >= 0; i--) {
    // Boot budget guard: nothing further from the head can fit — stop
    // BEFORE formatting it (monster messages are the boot-cost driver).
    if (entries.isNotEmpty && rows >= rowBudget) break;
    final message = messages[i];
    if (message is ToolResultMessage) {
      // Results render attached to their call's row, never standalone —
      // but a skipped result still counts as the replay's first message.
      firstIndex = i;
      continue;
    }
    var entry = tui
        ? replayLinesTui(
            message,
            width: width,
            dim: dim,
            results: results,
            cwd: cwd,
            home: home,
          )
        : replayLines(
            message,
            maxRows: maxRowsPerMessage,
            results: results,
            cwd: cwd,
            home: home,
          );
    if (entry.isEmpty) {
      firstIndex = i;
      continue;
    }
    if (!_replayEntryFits(entry, entries, rows, rowBudget)) break;
    // A single marathon message must not stall the boot replay: clip its
    // head with an explicit marker (the tail stays intact — messages at
    // the END are kept whole as long as the row budget lasts).
    entry = _clipReplayEntry(entry, dim);
    entries.insert(0, entry);
    rows += entry.length;
    firstIndex = i;
  }
  return (_withFenceFixup(messages, firstIndex, entries), firstIndex);
}

/// Whether a formatted replay [entry] still fits the boot [rowBudget]:
/// the first entry always fits (a lone message must never be dropped
/// wholesale), later ones only while the budget lasts.
bool _replayEntryFits(
  List<String> entry,
  List<List<String>> entries,
  int rows,
  int rowBudget,
) => entries.isEmpty || rows + entry.length <= rowBudget;

/// Clips a marathon entry's head with an explicit marker (the tail stays
/// intact — messages at the END are kept whole as long as the budget
/// lasts).
List<String> _clipReplayEntry(List<String> entry, String Function(String) dim) {
  const perMessageCap = 48;
  if (entry.length <= perMessageCap) return entry;
  return [
    ...entry.take(perMessageCap - 1),
    dim('… (replay clipped: ${entry.length - perMessageCap + 1} more rows)'),
  ];
}

/// The kept region may begin INSIDE a fenced code block whose opener was
/// dropped with the over-budget head: the view formats the history as one
/// markdown stream, so the region's first (originally closing) fence would
/// toggle state ON and swallow everything after it. Open a synthetic fence
/// to keep the kept region's fence lines balanced.
List<List<String>> _withFenceFixup(
  List<Message> messages,
  int firstIndex,
  List<List<String>> entries,
) {
  if (firstIndex > 0 &&
      entries.isNotEmpty &&
      _fenceOpenBefore(messages, firstIndex)) {
    return [
      const ['```'],
      ...entries,
    ];
  }
  return entries;
}

/// Whether the text of messages BEFORE [firstIndex] leaves a code fence
/// open (mirrors what the replay emits: user text and assistant text; tool
/// results never render). Every fence line toggles the state, so the count
/// of fence lines decides — one regex pass, no per-line list allocations
/// (a 30k-record resume must not materialize the whole transcript here).
bool _fenceOpenBefore(List<Message> messages, int firstIndex) {
  var fences = 0;
  for (var i = 0; i < firstIndex; i++) {
    final message = messages[i];
    final String? text = switch (message) {
      UserMessage(:final content) => _blocksText(content),
      AssistantMessage(:final content) =>
        content.whereType<TextContent>().map((b) => b.text).join('\n'),
      _ => null,
    };
    if (text == null) continue;
    fences += _fenceLineRe.allMatches(text).length;
  }
  return fences.isOdd;
}

/// omp transcript chrome (issue #807, parent #802 S4): message dividers,
/// the user-message bubble band, and phase-tinted tool cards — the omp
/// visual grammar ported to fa's theme roles.
///
/// Reference shapes are pinned to oh-my-pi's source (can1357/oh-my-pi,
/// MIT): the divider reproduces `chrome/message-divider.ts` exactly
/// (`ruleWidth = min(10, width - labelWidth - 1)`, blank rows around), the
/// bubble reproduces `chat/user-message.ts` (full-width `userMessageBg`
/// band, padding 1×1), and the tool card composes `render/status-line.ts`'s
/// header grammar with `render/utils.ts`'s `getStateBgColor` tints. Where
/// the issue text and omp's pinned source disagree (the issue's
/// `max(10, …)` divider formula), the SOURCE wins — parity is measured
/// against omp, not the prose.
///
/// Rules inherited from the repo's theming contract:
/// - Width/layout math runs on RAW strings (#279 E1); paint happens at
///   emit time through [FaThemeController], so a mid-session `/theme`
///   switch repaints the next frame.
/// - No profile (`NO_COLOR`/`TERM=dumb`) degrades deterministically:
///   structure (band rows, rules, glyphs) stays, every escape drops.
/// - Bubble rows are emitted PRE-STYLED (bg SGR prefix) under the same
///   contract as the live echo: the view-time markdown pass re-pads and
///   repaints them from the CURRENT theme, so stored lines never freeze
///   a stale palette.
library;

// ignore: implementation_imports — dart_tui's barrel exports no Style (issue #613); vendored fork only.
import 'package:dart_tui/src/bubbles/style.dart' show Style;
import '../types.dart' show ContentBlock, TextContent;
import 'ansi_markdown.dart' show AnsiMarkdown;
import 'tui_text_width.dart';
import 'tui_theme.dart';

/// Master switch for the omp transcript chrome (issue #807). Flipping this
/// off restores the legacy transcript bytes (`tui.classic` kill switch,
/// umbrella decision D1 — the config key lands with the config-story
/// sibling; until then tests and the classic REG guard flip this flag).
var tuiChromeEnabled = true;

/// A tool card's lifecycle phase (issue #807): picks the status glyph, the
/// title/glyph color, and the card tint — omp's `ToolCardPhase` narrowed to
/// the states fa's transcript actually renders.
enum TuiCardPhase { pending, running, success, error }

/// Status glyphs per omp's `theme/symbols.ts` defaults (`status.*`).
/// gh-1446 AC8: the pending hourglass and the running spinner resolve
/// through the symbol table (`status.pending` = `○`, `status.running` =
/// `◐`) — no hardcoded `⏳`/`⟳` survives in chrome code.
String tuiCardGlyph(TuiCardPhase phase) => switch (phase) {
  TuiCardPhase.pending => FaThemeController.instance.sym('status.pending'),
  TuiCardPhase.running => FaThemeController.instance.sym('status.running'),
  TuiCardPhase.success => '✔',
  TuiCardPhase.error => '✘',
};

/// The divider's raw layout (omp `#renderDivider`): a short left rule, a
/// space, then the label. `ruleWidth = min([ruleWidth], width - labelWidth
/// - 1)`; below one rule cell the label alone renders, truncated to
/// [width]. RAW text in, RAW text out — callers own the paint role
/// (the replay resume boundary paints it dim).
String tuiMessageDividerLayout(String label, int width, {int ruleWidth = 10}) {
  width = width < 1 ? 1 : width;
  final labelWidth = tuiTextWidth(label);
  final budget = width - labelWidth - 1;
  final rule = ruleWidth < budget ? ruleWidth : budget;
  if (rule < 1) return tuiFitWidth(label, width);
  return '${'─' * rule} $label';
}

/// The user-message bubble (omp `chat/user-message.ts`): the message body
/// on the full-width [TuiTheme.userMessageBg] band, one blank band row
/// above and below (padding 1×1), one leading space per content row
/// (paddingX 1). Rows are emitted PRE-STYLED so the view-time formatter
/// pads them to the then-current width and repaints from the current
/// theme; without a profile they degrade to plain rows (leading space
/// kept — the band's ghost of structure).
List<String> tuiUserBubble(List<String> contentLines) => [
  tuiUserMessageLine(''),
  for (final line in contentLines) tuiUserMessageLine(' $line'),
  tuiUserMessageLine(''),
];

/// Header fields for one tool card (omp `StatusLineOptions`, narrowed).
final class ToolCardSegments {
  const ToolCardSegments({
    required this.title,
    this.description = '',
    this.badge = '',
    this.meta = const [],
  });

  /// The tool label (`bash`, `read`, …) — painted in the accent role.
  final String title;

  /// The human detail (command, path, question) — muted, absorbs squeeze.
  final String description;

  /// Bracketed status badge (e.g. `exit 1`) — painted in the phase color.
  final String badge;

  /// Dot-joined dim meta fragments (elapsed, line counts).
  final List<String> meta;
}

/// The painted card header (omp `renderStatusLine`):
/// `glyph title: description [badge] meta·meta`, fitted to [width] cells.
/// Squeeze drops from the tail — meta first, then the badge, then the
/// description ellipsizes; the glyph+title always fit (ellipsized only
/// past that).
String tuiToolCardHeader(ToolCardSegments s, TuiCardPhase phase, int width) {
  final c = FaThemeController.instance;
  final styled = c.profile != null;
  String paint(String piece, String Function(String) role) =>
      styled ? role(piece) : piece;

  // Fit FIRST, paint second — painting an unfitted run would emit a head
  // wider than the card (the fitted/unfitted drift the UT pins).
  final (glyph, title) = _fitCardHead(s.title, tuiCardGlyph(phase), width);
  final headRaw =
      paint(glyph, (g) => c.border(_phaseStyle(c, phase), g)) +
      paint(title.isEmpty ? '' : ' $title', (t) => c.accent(t));
  final remain = width - tuiTextWidth('$glyph $title');

  final tail = _squeezeCardTail(s, remain);
  return headRaw + _paintCardTail(c, phase, tail, paint);
}

/// The width-fitted head: the glyph plus the title ellipsized to the
/// remaining budget (empty title when even the glyph can't fit).
(String, String) _fitCardHead(String title, String glyph, int width) {
  final titleBudget = width - tuiTextWidth(glyph) - 1;
  if (titleBudget < 1) return (tuiFitWidth(glyph, width), '');
  if (tuiTextWidth(title) > titleBudget) {
    return (glyph, tuiFitWidth(title, titleBudget));
  }
  return (glyph, title);
}

/// The fitted tail segments, decided on RAW widths. Squeeze drops from
/// the tail — meta first, then the badge, then the description
/// ellipsizes.
(String, String, String) _squeezeCardTail(ToolCardSegments s, int remain) {
  final descRaw = s.description.isEmpty ? '' : ': ${s.description}';
  final badgeRaw = s.badge.isEmpty ? '' : ' [${s.badge}]';
  final meta = s.meta.where((m) => m.trim().isNotEmpty).toList();
  final metaRaw = meta.isEmpty ? '' : ' ${meta.join('·')}';

  if (tuiTextWidth('$descRaw$badgeRaw$metaRaw') <= remain) {
    return (descRaw, badgeRaw, metaRaw);
  }
  if (tuiTextWidth('$descRaw$badgeRaw') <= remain) {
    return (descRaw, badgeRaw, '');
  }
  if (tuiTextWidth(descRaw) > remain) {
    return (remain > 0 ? tuiFitWidth(descRaw, remain) : '', '', '');
  }
  return (descRaw, '', '');
}

/// Paints the surviving tail in each piece's documented role
/// (ToolCardSegments): description muted — bright in the error phase,
/// #366's keep-failure-text-bright — badge in the phase color, meta dim.
String _paintCardTail(
  FaThemeController c,
  TuiCardPhase phase,
  (String, String, String) tail,
  String Function(String, String Function(String)) paint,
) {
  final (desc, badge, meta) = tail;
  return (desc.isEmpty
          ? ''
          : paint(
              desc,
              phase == TuiCardPhase.error
                  ? (t) => c.error(t)
                  : (t) => c.toolOutput(t),
            )) +
      (badge.isEmpty
          ? ''
          : paint(badge, (t) => c.border(_phaseStyle(c, phase), t))) +
      (meta.isEmpty ? '' : paint(meta, (t) => c.muted(t)));
}

/// The card tint's raw background SGR prefix ('' without a profile).
///
/// success/error/pending map to the [TuiTheme.toolSuccessBg]/
/// [TuiTheme.toolErrorBg]/[TuiTheme.toolPendingBg] tints.
String tuiCardTintSgr(TuiCardPhase phase) {
  final c = FaThemeController.instance;
  if (c.profile == null) return '';
  return switch (phase) {
    TuiCardPhase.success => c.toolSuccessBgSgr(),
    TuiCardPhase.error => c.toolErrorBgSgr(),
    _ => c.toolPendingBgSgr(),
  };
}

Style _phaseStyle(FaThemeController c, TuiCardPhase phase) => switch (phase) {
  TuiCardPhase.success => c.cardSuccessStyle,
  TuiCardPhase.error => c.cardErrorStyle,
  TuiCardPhase.pending => c.cardPendingStyle,
  TuiCardPhase.running => c.cardRunningStyle,
};

/// The bordered tool card (omp's generic tinted card + status header):
/// the header row, up to [maxDetailLines] tinted detail rows padded to
/// [width], and a `… N more lines` footer when detail was cut (omp's
/// `buildStatusFooter` hidden-line count, hint suffix dropped — fa cards
/// are not ctrl+o-expandable yet). Each row carries the phase tint as a
/// background; without a profile the card degrades to plain rows.
List<String> tuiToolCard(
  ToolCardSegments segments,
  TuiCardPhase phase,
  int width, {
  List<String> detailLines = const [],
  int maxDetailLines = 3,
}) {
  final tint = tuiCardTintSgr(phase);
  // Detail rows are width-fitted BEFORE painting — an overlong line would
  // break the card's right edge (paintRow only pads short rows). The
  // header is already composed to [width] and is STYLED — fitting it with
  // [tuiFitWidth] (raw-string contract) would chop mid-SGR.
  // Padding measures VISIBLE cells — the styled row's escapes are
  // zero-width at the terminal (same contract as the view-time echo pad).
  String paintRow(String row, {bool fit = true}) {
    final fitted = fit ? tuiFitWidth(row, width) : row;
    if (tint.isEmpty) return fitted;
    final pad =
        width -
        tuiTextWidth(fitted.replaceAll(AnsiMarkdown.ansiSgrPattern, ''));
    return '$tint$fitted${pad > 0 ? ' ' * pad : ''}\x1b[0m';
  }

  return [
    paintRow(tuiToolCardHeader(segments, phase, width), fit: false),
    ..._previewLines(detailLines, maxDetailLines).map((line) => paintRow(line)),
  ];
}

/// A failed result's first text line — the news the error card (and the
/// legacy error row) leads with, kept bright (#366).
String failureFirstLine(List<ContentBlock> content) => content
    .whereType<TextContent>()
    .map((block) => block.text)
    .join()
    .split('\n')
    .first;

/// The settled tool end-row BOTH edges paint (issue #807 live, #916 replay
/// parity): the phase-tinted band card for [toolName] with [successDetail]
/// as the description — or, on error, [failureFirstLine] of
/// [resultContent] (the failure text is the news). [meta] carries the
/// trailing dim fragments: the live elapsed cell (`0s`) or the replay's
/// honest `—` (the one permitted live/replay difference, issue #446
/// contract point 2). Empty fragments drop (the live path passes its
/// unpainted elapsed verbatim).
///
/// [interrupted] is the replay-only state — the call's result never landed
/// (crash mid-turn): error phase over the plain args preview, never a bare
/// `[name]` marker.
///
/// ONE source for live (`_onToolExecutionEnd`) and replay
/// ([replayToolRow]) — the parity drift class that was #916 is closed by
/// construction, not by test-mirrored hope.
List<String> settledToolCardRows({
  required String toolName,
  required String successDetail,
  required bool isError,
  required int width,
  List<ContentBlock> resultContent = const [],
  List<String> meta = const [],
  bool interrupted = false,
}) {
  return tuiToolCard(
    ToolCardSegments(
      title: toolName,
      description: isError ? failureFirstLine(resultContent) : successDetail,
      meta: [
        for (final m in meta)
          if (m.trim().isNotEmpty) m,
      ],
    ),
    isError || interrupted ? TuiCardPhase.error : TuiCardPhase.success,
    width,
  );
}

/// Collapses [lines] to at most [maxLines] rows, appending omp's
/// `… N more lines` footer when something was cut.
List<String> _previewLines(List<String> lines, int maxLines) {
  if (lines.length <= maxLines) return lines;
  return [...lines.take(maxLines), '… ${lines.length - maxLines} more lines'];
}

